tape( 'the function supports providing a stride parameter for `x`', function test( t ) {
	var expected;
	var out;
	var x;

	x = [
		-5.0,   // 0
		3.0,
		-2.0,   // 1
		8.0,
		-1.0,   // 2
		6.0
	];
	out = [ 0.0, 0.0, 0.0 ];
	expected = [ -5.0, -2.0, -1.0 ];

	maxk( 3, 3, x, 2, 0, out, 1, 0 );

	t.deepEqual( out, expected, 'returns expected value' );
	t.end();
});

